function solution(nums1, nums2) {
  let a = nums1, b = nums2;
  if (a.length > b.length) [a, b] = [b, a];
  let lo = 0, hi = a.length;
  while (lo <= hi) {
    const i = (lo + hi) >> 1;
    const j = ((a.length + b.length + 1) >> 1) - i;
    const aL = i === 0 ? -Infinity : a[i - 1];
    const aR = i === a.length ? Infinity : a[i];
    const bL = j === 0 ? -Infinity : b[j - 1];
    const bR = j === b.length ? Infinity : b[j];
    if (aL <= bR && bL <= aR) {
      const total = a.length + b.length;
      const left = Math.max(aL, bL);
      return total % 2 ? left : (left + Math.min(aR, bR)) / 2;
    }
    if (aL > bR) hi = i - 1;
    else lo = i + 1;
  }
  return 0;
}
